import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2020-01-30 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2020-01-30 -- Ceph Performance Meeting","date":"2020-01-30T00:00:00.000Z","updated":"2020-04-01T00:00:00.000Z","tags":["Ceph","性能优化","CI系统改进","分布式存储","代码逻辑简化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-01-30_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2020/2020-01-30_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),s={name:"posts/2020/2020-01-30_-_-_Ceph_Performance_Meeting.md"};function l(n,e,i,g,_,d){return r(),a("div",null,[...e[0]||(e[0]=[o('<p>在 2020 年 1 月 30 日的 Ceph 性能会议上，研发人员和内容审核专家讨论了多个关键议题，包括性能优化、代码逻辑简化、CI 系统改进以及具体的 Pull Requests (PRs)。</p><h3 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h3><ul><li><strong>新 PR 介绍</strong>：会议开始时，介绍了包括 Casey 和 Braddock 的优化 buffer lists 的 PR。</li><li><strong>Igor 的 PR</strong>：Igor 提交了一个简化 Onoda pin 和 unpin 逻辑的 PR，解决了之前修复时引入的复杂性和潜在的竞态条件问题。</li><li><strong>Zone Commodity 配置</strong>：讨论了允许 zone commodity 配置 index charts 的 PR，包括增加 bucket shards 数量的简单更改。</li><li><strong>PG autoscaler 更新</strong>：一个将默认 PG 数量增加到 32 的 PR 已合并，旨在提高 OSD 对更多 PG 的响应性。</li><li><strong>Bufferless 和 Buffer List 优化</strong>：Radek 和 Corel 讨论了优化 buffer list 大小的旧努力，包括使用迭代器和减少内存占用。</li></ul><h3 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h3><ul><li><strong>性能优化</strong>：重点讨论了通过优化 buffer lists 和调整 PG 数量来提高性能。</li><li><strong>简化逻辑</strong>：强调了简化代码逻辑的重要性，如 Igor 的 PR 所示。</li><li><strong>CI 和测试</strong>：讨论了 CI 系统的改进，包括增加对 master 分支的 CI 支持和对不同基准测试的性能比较。</li></ul><h3 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h3><ul><li><strong>合并 PR</strong>：多个 PR 被合并或准备合并，包括优化 PG 数量和 bufferless 使用的 PR。</li><li><strong>CI 改进</strong>：决定继续改进 CI 系统，增加对更多基准测试的支持。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li><strong>继续优化</strong>：继续关注和优化 buffer lists 和 PG autoscaler。</li><li><strong>CI 系统升级</strong>：继续升级 CI 系统，确保所有测试环境的一致性和最新性。</li><li><strong>性能测试</strong>：进行更多的性能测试，特别是在不同硬件和配置下的测试。</li></ul><h3 id="其他讨论点" tabindex="-1">其他讨论点 <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点&quot;">​</a></h3><ul><li><strong>SSD 性能问题</strong>：讨论了 SSD 性能问题，特别是关于队列大小和服务时间的优化。</li><li><strong>环境升级</strong>：讨论了测试环境的升级，包括从 CentOS 7 升级到更高版本。</li></ul><p>会议最后，主持人宣布将休息两周，期间可能不会有会议。整体上，会议聚焦于性能优化和 CI 系统的改进，同时讨论了具体的 PR 和未来的工作方向。</p>',12)])])}const c=t(s,[["render",l]]);export{h as __pageData,c as default};
